// Standalone SDR-SDRAM hardware diagnostic for the Tang Console 138K.
// The HDMI picture is blue during initialization, green after all line tests
// pass, and red on the first readback mismatch.  Each location is initialized
// with a full 128-bit write, then updated one 32-bit lane at a time using the
// same byte-mask shape generated by the Voodoo framebuffer path.  The complete
// line is read and compared after every partial write.
module sdram_bist_top (
    input  wire        clk50,
    input  wire        uart_rx,
    output wire        uart_tx,
    input  wire        key0_n,
    input  wire        key1_n,
    inout  wire        usb_soft_dp,
    inout  wire        usb_soft_dn,
    output wire        usb_pullup_en,
    output wire [1:0]  led_n,
    output wire        tmds_clk_p,
    output wire        tmds_clk_n,
    output wire [2:0]  tmds_data_p,
    output wire [2:0]  tmds_data_n,
    output wire [12:0] O_sdram_addr,
    output wire [1:0]  O_sdram_ba,
    output wire        O_sdram_cs_n,
    output wire        O_sdram_ras_n,
    output wire        O_sdram_cas_n,
    output wire        O_sdram_wen_n,
    output wire        O_sdram_cke,
    output wire        O_sdram_clk,
    output wire [1:0]  O_sdram_dqm,
    inout  wire [15:0] IO_sdram_dq
);
    wire clk_mem;
    wire clk_core_unused;
    wire clk_sdram_pin;
    wire pll_mem_lock;
    console_sdram_pll u_mem_pll (
        .clkin(clk50), .core_clk(clk_core_unused), .sdram_clk(clk_mem),
        .sdram_pin_clk(clk_sdram_pin), .lock(pll_mem_lock)
    );
    assign O_sdram_clk = clk_sdram_pin;

    reg [7:0] reset_pipe = 8'd0;
    always @(posedge clk_mem)
        reset_pipe <= pll_mem_lock ? {reset_pipe[6:0], 1'b1} : 8'd0;
    wire rst = ~reset_pipe[7];

    reg  [2:0]   cmd;
    reg          cmd_en;
    reg  [27:0]  addr;
    reg  [127:0] wr_data;
    reg  [15:0]  wr_data_mask;
    reg          wr_data_en;
    wire         cmd_ready;
    wire         wr_data_rdy;
    wire [127:0] rd_data;
    wire         rd_data_valid;
    wire         init_complete;

    sdram_line_controller u_sdram (
        .clk(clk_mem), .reset(rst),
        .cmd_ready(cmd_ready), .cmd(cmd), .cmd_en(cmd_en), .addr(addr),
        .wr_data_rdy(wr_data_rdy), .wr_data(wr_data),
        .wr_data_en(wr_data_en), .wr_data_end(1'b1),
        .wr_data_mask(wr_data_mask), .rd_data(rd_data),
        .rd_data_valid(rd_data_valid), .rd_data_end(),
        .init_complete(init_complete),
        .O_sdram_addr(O_sdram_addr), .O_sdram_ba(O_sdram_ba),
        .O_sdram_cs_n(O_sdram_cs_n), .O_sdram_ras_n(O_sdram_ras_n),
        .O_sdram_cas_n(O_sdram_cas_n), .O_sdram_wen_n(O_sdram_wen_n),
        .O_sdram_cke(O_sdram_cke), .O_sdram_dqm(O_sdram_dqm),
        .IO_sdram_dq(IO_sdram_dq)
    );

    function automatic [23:0] test_addr(input [2:0] index);
        case (index)
            3'd0: test_addr = 24'h000000;
            3'd1: test_addr = 24'h0001f8;
            3'd2: test_addr = 24'h000200;
            3'd3: test_addr = 24'h3ffff8;
            3'd4: test_addr = 24'h400000;
            3'd5: test_addr = 24'h800000;
            3'd6: test_addr = 24'hc00000;
            default: test_addr = 24'hfffff8;
        endcase
    endfunction

    function automatic [127:0] test_data(input [2:0] index);
        test_data = {
            16'hf000 | {13'd0,index}, 16'he100 | {13'd0,index},
            16'hd200 | {13'd0,index}, 16'hc300 | {13'd0,index},
            16'hb400 | {13'd0,index}, 16'ha500 | {13'd0,index},
            16'h9600 | {13'd0,index}, 16'h8700 | {13'd0,index}
        };
    endfunction

    function automatic [31:0] lane_data(
        input [2:0] index,
        input [1:0] lane
    );
        lane_data = {8'hd0 | {6'd0, lane}, 5'h15, index,
                     8'h60 | {6'd0, lane}, 5'h0a, index};
    endfunction

    localparam [3:0] B_WAIT_INIT = 0, B_BASE_WRITE_ISSUE = 1,
                     B_WRITE_WAIT_BUSY = 2, B_WRITE_WAIT_READY = 3,
                     B_LANE_WRITE_ISSUE = 4, B_LANE_WAIT_BUSY = 5,
                     B_LANE_WAIT_READY = 6, B_READ_ISSUE = 7,
                     B_READ_WAIT = 8, B_NEXT = 9,
                     B_PASS = 10, B_FAIL = 11;
    reg [3:0] bist_state;
    reg [2:0] test_index;
    reg [1:0] lane_index;
    reg [127:0] expected;
    reg [127:0] observed;

    always @(posedge clk_mem) begin
        if (rst) begin
            bist_state <= B_WAIT_INIT;
            test_index <= 0;
            cmd <= 0;
            cmd_en <= 0;
            addr <= 0;
            wr_data <= 0;
            wr_data_mask <= 16'hffff;
            wr_data_en <= 0;
            expected <= 0;
            observed <= 0;
        end else begin
            cmd_en <= 0;
            wr_data_en <= 0;
            case (bist_state)
                B_WAIT_INIT: if (init_complete) bist_state <= B_BASE_WRITE_ISSUE;
                B_BASE_WRITE_ISSUE: if (cmd_ready && wr_data_rdy) begin
                    cmd <= 3'd0;
                    addr <= {4'd0, test_addr(test_index)};
                    wr_data <= test_data(test_index);
                    wr_data_mask <= 16'h0000;
                    cmd_en <= 1;
                    wr_data_en <= 1;
                    expected <= test_data(test_index);
                    lane_index <= 0;
                    bist_state <= B_WRITE_WAIT_BUSY;
                end
                B_WRITE_WAIT_BUSY: if (!cmd_ready) bist_state <= B_WRITE_WAIT_READY;
                B_WRITE_WAIT_READY: if (cmd_ready) bist_state <= B_LANE_WRITE_ISSUE;
                B_LANE_WRITE_ISSUE: if (cmd_ready && wr_data_rdy) begin
                    cmd <= 3'd0;
                    addr <= {4'd0, test_addr(test_index)};
                    wr_data <= 128'd0;
                    wr_data[lane_index * 32 +: 32] <= lane_data(test_index, lane_index);
                    wr_data_mask <= ~(16'h000f << (lane_index * 4));
                    expected[lane_index * 32 +: 32] <= lane_data(test_index, lane_index);
                    cmd_en <= 1;
                    wr_data_en <= 1;
                    bist_state <= B_LANE_WAIT_BUSY;
                end
                B_LANE_WAIT_BUSY: if (!cmd_ready) bist_state <= B_LANE_WAIT_READY;
                B_LANE_WAIT_READY: if (cmd_ready) bist_state <= B_READ_ISSUE;
                B_READ_ISSUE: if (cmd_ready) begin
                    cmd <= 3'd1;
                    addr <= {4'd0, test_addr(test_index)};
                    cmd_en <= 1;
                    bist_state <= B_READ_WAIT;
                end
                B_READ_WAIT: if (rd_data_valid) begin
                    observed <= rd_data;
                    bist_state <= (rd_data == expected) ? B_NEXT : B_FAIL;
                end
                B_NEXT: if (lane_index != 2'd3) begin
                            lane_index <= lane_index + 1'b1;
                            bist_state <= B_LANE_WRITE_ISSUE;
                        end else if (test_index == 3'd7) begin
                            bist_state <= B_PASS;
                        end else begin
                            test_index <= test_index + 1'b1;
                            bist_state <= B_BASE_WRITE_ISSUE;
                        end
                default: ;
            endcase
        end
    end

    wire bist_pass = bist_state == B_PASS;
    wire bist_fail = bist_state == B_FAIL;

    wire pll_hdmi_lock;
    wire clk_hdmi_serial;
    wire clk_hdmi_pixel;
    Gowin_PLL_Hdmi u_pll_hdmi (
        .lock(pll_hdmi_lock), .clkout0(clk_hdmi_serial), .clkin(clk50)
    );
    CLKDIV #(.DIV_MODE("5")) u_hdmi_div (
        .HCLKIN(clk_hdmi_serial), .RESETN(pll_hdmi_lock),
        .CALIB(1'b0), .CLKOUT(clk_hdmi_pixel)
    );

    reg [9:0] h_count;
    reg [9:0] v_count;
    always @(posedge clk_hdmi_pixel) begin
        if (!pll_hdmi_lock) begin
            h_count <= 0;
            v_count <= 0;
        end else if (h_count == 799) begin
            h_count <= 0;
            v_count <= (v_count == 524) ? 0 : v_count + 1'b1;
        end else h_count <= h_count + 1'b1;
    end
    wire de = h_count < 640 && v_count < 480;
    wire hs = !(h_count >= 656 && h_count < 752);
    wire vs = !(v_count >= 490 && v_count < 492);
    wire [7:0] red   = bist_fail ? 8'hff : 8'h00;
    wire [7:0] green = bist_pass ? 8'hff : 8'h00;
    wire [7:0] blue  = (!bist_pass && !bist_fail) ? 8'hff : 8'h00;

    DVI_TX_Top u_dvi (
        .I_rst_n(pll_hdmi_lock), .I_serial_clk(clk_hdmi_serial),
        .I_rgb_clk(clk_hdmi_pixel), .I_rgb_vs(vs), .I_rgb_hs(hs),
        .I_rgb_de(de), .I_rgb_r(red), .I_rgb_g(green), .I_rgb_b(blue),
        .O_tmds_clk_p(tmds_clk_p), .O_tmds_clk_n(tmds_clk_n),
        .O_tmds_data_p(tmds_data_p), .O_tmds_data_n(tmds_data_n)
    );

    assign led_n = bist_fail ? 2'b01 : (bist_pass ? 2'b10 : 2'b11);
    assign uart_tx = uart_rx;
    assign usb_soft_dp = 1'bz;
    assign usb_soft_dn = 1'bz;
    assign usb_pullup_en = 1'b0;
    wire _unused = &{1'b0, key0_n, key1_n, observed[0]};
endmodule
